int main() {
    string line;
    while (getline(cin, line)) {
        if (line.empty()) continue;
        stringstream ss(line);
        int start, end, hour, minute;
        char colon;
        ss >> start >> end >> hour >> colon >> minute;

        int distance = abs(end - start);
        int fee;
        if (distance <= 40) {
            int start_time = hour * 60 + minute;
            int end_time = start_time + 10; // assume 10 min travel time for discount window check
            // Discount applies from 17:30 (1050) to 19:30 (1170)
            bool discount = false;
            // Check if any part of the trip overlaps with discount period
            if (!(end_time <= 1050 || start_time >= 1170)) {
                discount = true;
            }
            if (discount) {
                fee = (distance * 250 + 1) / 2; // half fee
            } else {
                fee = distance * 250;
            }
        } else {
            fee = distance * 250;
        }

        // Round up to nearest 50 yen
        fee = ((fee + 49) / 50) * 50;
        cout << fee << endl;
    }
    return 0;
}

