int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Toll table between consecutive interchanges
    // 1: Seya, 2: Yokohama-Machida, 3: Kawasaki, 4: Tokyo
    // Distances (km): 13.3, 16.3, 18.9
    // Fees (yen):     500, 600, 700
    //
    // Thus:
    // 1-2: 500
    // 2-3: 600
    // 3-4: 700
    // Any pair fee is the sum over the interval.
    vector<int> pos = {0, 0, 13, 29, 48}; // only for distance comparison (actual sums below)
    int feeSeg[5][5] = {};
    feeSeg[1][2] = feeSeg[2][1] = 500;
    feeSeg[2][3] = feeSeg[3][2] = 600;
    feeSeg[3][4] = feeSeg[4][3] = 700;

    map<string, int> id = {
        {"Seya", 1},
        {"Yokohama", 2},
        {"Machida", 2},
        {"Yokohama-Machida", 2},
        {"Kawasaki", 3},
        {"Tokyo", 4}
    };

    string a, b, t;
    while (cin >> a >> b >> t) {
        if (a == "#" && b == "#" && t == "#") break;

        int s = id[a], e = id[b];
        if (s > e) swap(s, e);

        int dist = 0, fee = 0;
        for (int i = s; i < e; i++) {
            if (i == 1) dist += 13;
            else if (i == 2) dist += 16;
            else if (i == 3) dist += 19;

            fee += feeSeg[i][i + 1];
        }

        int hh = stoi(t.substr(0, 2));
        int mm = stoi(t.substr(3, 2));
        int minutes = hh * 60 + mm;

        if (17 * 60 + 30 <= minutes && minutes <= 19 * 60 + 30 && dist <= 40) {
            fee = (fee + 1) / 2;            // half, rounded up to 1 yen first if needed
            fee = ((fee + 49) / 50) * 50;   // round up to nearest 50 yen
        }

        cout << fee << '\n';
    }

    return 0;
}

import java.util.Scanner;

public class TollFeeCalculator {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNext()) {
            String startInterchange = sc.next();
            if (startInterchange.equals("-")) break;
            String endInterchange = sc.next();
            String startTime = sc.next();
            String endTime = sc.next();

            int distance = calculateDistance(startInterchange, endInterchange);
            int fee = calculateFee(distance, startTime, endTime);
            System.out.println(fee);
        }
        sc.close();
    }

    private static int calculateDistance(String start, String end) {
        String[] interchanges = {"A", "B", "C", "D", "E", "F", "G", "H"};
        int[] distances = {0, 6, 13, 18, 23, 43, 53, 63};

        int startIdx = -1, endIdx = -1;
        for (int i = 0; i < interchanges.length; i++) {
            if (interchanges[i].equals(start)) startIdx = i;
            if (interchanges[i].equals(end)) endIdx = i;
        }

        return Math.abs(distances[endIdx] - distances[startIdx]);
    }

    private static int calculateFee(int distance, String startTime, String endTime) {
        int baseFee = distance * 100; // 100 yen per km example rate
        boolean isDiscountPeriod = isInDiscountPeriod(startTime, endTime);

        if (isDiscountPeriod && distance <= 40) {
            baseFee = (int) Math.ceil(baseFee / 2.0 / 50) * 50;
        } else {
            baseFee = (int) Math.ceil(baseFee / 50.0) * 50;
        }

        return baseFee;
    }

    private static boolean isInDiscountPeriod(String startTime, String endTime) {
        int startMinutes = timeToMinutes(startTime);
        int endMinutes = timeToMinutes(endTime);

        int discountStart = 17 * 60 + 30;
        int discountEnd = 19 * 60 + 30;

        // Check if the travel overlaps with discount period
        return (startMinutes < discountEnd && endMinutes > discountStart);
    }

    private static int timeToMinutes(String time) {
        String[] parts = time.split(":");
        int hours = Integer.parseInt(parts[0]);
        int minutes = Integer.parseInt(parts[1]);
        return hours * 60 + minutes;
    }
}

