import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt(); // number of interchanges
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = fs.nextInt();

        int[][] fee = new int[n][n];
        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                fee[i][j] = fs.nextInt();
            }
        }

        int m = fs.nextInt(); // number of queries
        StringBuilder out = new StringBuilder();

        for (int q = 0; q < m; q++) {
            int h = fs.nextInt();
            int min = fs.nextInt();
            int s = fs.nextInt() - 1;
            int t = fs.nextInt() - 1;

            if (s > t) {
                int tmp = s;
                s = t;
                t = tmp;
            }

            int ans = fee[s][t];
            int d = Math.abs(dist[t] - dist[s]);

            // Discount applies from 17:30 to 19:30 inclusive, for distance <= 40km
            if ((h > 17 || (h == 17 && min >= 30)) &&
                (h < 19 || (h == 19 && min <= 30)) &&
                d <= 40) {
                ans = (ans + 1) / 2; // half, rounded up to integer yen first
            }

            // Round up to nearest 50 yen
            ans = ((ans + 49) / 50) * 50;
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}

