typedef struct {
    const char *name;
    int dist;
} IC;

static IC ics[] = {
    {"Suwon", 0},
    {"Osan", 14},
    {"Pyeongtaek", 36},
    {"Cheonan", 67},
    {"Daejeon", 129},
    {"Daegu", 290},
    {"Busan", 416}
};

static int find_dist(const char *name) {
    int n = (int)(sizeof(ics) / sizeof(ics[0]));
    for (int i = 0; i < n; i++) {
        if (strcmp(name, ics[i].name) == 0) return ics[i].dist;
    }
    return -1;
}

static int ceil50(int x) {
    return ((x + 49) / 50) * 50;
}

static int calc_fee(int d) {
    if (d <= 10) return 500;
    return 500 + ((d - 10 + 9) / 10) * 200;
}

int main(void) {
    char start[64], end[64], time[64];

    while (scanf("%63s %63s %63s", start, end, time) == 3) {
        int ds = find_dist(start);
        int de = find_dist(end);
        int dist = abs(de - ds);

        int fee = calc_fee(dist);

        int h, m;
        sscanf(time, "%d:%d", &h, &m);
        int minutes = h * 60 + m;

        if (minutes >= 17 * 60 + 30 && minutes <= 19 * 60 + 30 && dist <= 40) {
            fee = ceil50((fee + 1) / 2);
        }

        printf("%d\n", fee);
    }

    return 0;
}
